import java.util.Scanner;

public class Main {
    static long[] x = new long[7];
    static long[] y = new long[7];

    static long cross(int a, int b, int c) {
        return (x[b] - x[a]) * (y[c] - y[a]) - (y[b] - y[a]) * (x[c] - x[a]);
    }

    static long dist2(int a, int b) {
        long dx = x[a] - x[b];
        long dy = y[a] - y[b];
        return dx * dx + dy * dy;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < 7; i++) {
            if (!sc.hasNextLong()) return;
            x[i] = sc.nextLong();
            y[i] = sc.nextLong();
        }

        // 1. Acute angle at P1
        long v1x = x[1] - x[0], v1y = y[1] - y[0];
        long v2x = x[2] - x[0], v2y = y[2] - y[0];
        if (v1x * v2x + v1y * v2y <= 0) { System.out.println("N"); return; }

        // 2. |P1P2| == |P1P3|
        if (dist2(0, 1) != dist2(0, 2)) { System.out.println("N"); return; }

        // 3. P2, P3, P4, P5 collinear
        if (cross(1, 2, 3) != 0 || cross(1, 2, 4) != 0) { System.out.println("N"); return; }

        // 4. Midpoints of P2P3 and P4P5 coincide
        if (x[1] + x[2] != x[3] + x[4] || y[1] + y[2] != y[3] + y[4]) { System.out.println("N"); return; }

        // 5. |P2P3| > |P4P5|
        if (dist2(1, 2) <= dist2(3, 4)) { System.out.println("N"); return; }

        // 6. P4P6 and P5P7 perpendicular to P2P3
        long baseX = x[2] - x[1];
        long baseY = y[2] - y[1];
        long v46x = x[5] - x[3];
        long v46y = y[5] - y[3];
        if (v46x * baseX + v46y * baseY != 0) { System.out.println("N"); return; }
        long v57x = x[6] - x[4];
        long v57y = y[6] - y[4];
        if (v57x * baseX + v57y * baseY != 0) { System.out.println("N"); return; }

        // 7. |P4P6| == |P5P7|
        if (dist2(3, 5) != dist2(4, 6)) { System.out.println("N"); return; }

        // 8. P1 and P6 separated by line P2P3
        long side1 = cross(1, 2, 0);
        long side6 = cross(1, 2, 5);
        if (!((side1 > 0 && side6 < 0) || (side1 < 0 && side6 > 0))) {
            System.out.println("N");
            return;
        }

        System.out.println("S");
    }
}
```

